  <script>
  function laToggleNav(){
    if (document.body.classList.contains('la-dash')) {
      document.body.classList.toggle('la-side-open');
      laSyncMenu();
      return;
    }
    var n=document.getElementById('laNav'); if(!n) return;
    n.classList.toggle('open');
    document.body.classList.toggle('la-nav-open', n.classList.contains('open'));
    laSyncMenu();
  }
  function laCloseNav(){
    document.body.classList.remove('la-side-open');
    var n=document.getElementById('laNav'); if(n) n.classList.remove('open');
    document.body.classList.remove('la-nav-open');
    laSyncMenu();
  }
  function laSyncMenu(){
    var on = document.body.classList.contains('la-side-open') || (document.getElementById('laNav') && document.getElementById('laNav').classList.contains('open'));
    document.querySelectorAll('.la-menu-btn, .la-dash-menu').forEach(function(b){
      b.classList.toggle('is-open', !!on);
      b.setAttribute('aria-expanded', on ? 'true' : 'false');
      var i=b.querySelector('i');
      if (i) i.className = on ? 'ri-close-line' : 'ri-menu-line';
    });
    var scrim = document.getElementById('laNavScrim');
    if (scrim) scrim.classList.toggle('is-on', document.body.classList.contains('la-nav-open'));
  }
  function laOpenLogin(e){ if (e) e.preventDefault(); laCloseNav(); var m=document.getElementById('laLogin'); if(m) m.classList.add('open'); }
  function laCloseLogin(){ var m=document.getElementById('laLogin'); if(m) m.classList.remove('open'); }
  function laSyncPack(){
    var pack = document.documentElement.getAttribute('data-la-pack') || 'peak';
    document.querySelectorAll('.la-pack-switch [data-pack]').forEach(function(b){
      var on = b.getAttribute('data-pack') === pack;
      b.classList.toggle('is-on', on);
      b.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
  }
  function laSetPack(pack){
    var allowed = {peak:1, violet:1, navy:1, light:1};
    if (!allowed[pack]) pack = 'peak';
    var root = document.documentElement;
    if (root.getAttribute('data-la-switch') === '0') return;
    root.setAttribute('data-la-pack', pack);
    root.classList.toggle('la-light', pack === 'light');
    try {
      localStorage.setItem('la-pack', pack);
      localStorage.setItem('la-theme', pack === 'light' ? 'light' : 'dark');
    } catch (e) {}
    laSyncPack();
  }
  function laToggleTheme(){
    var order = ['peak','violet','navy','light'];
    var cur = document.documentElement.getAttribute('data-la-pack') || 'peak';
    var i = order.indexOf(cur);
    laSetPack(order[(i + 1) % order.length]);
  }
  laSyncPack();
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') { laCloseLogin(); laCloseNav(); } });
  document.addEventListener('click', function(e){
    var n=document.getElementById('laNav'); if(!n || !n.classList.contains('open')) return;
    if (e.target.closest('.la-menu-btn')) return;
    if (e.target.closest('#laNavScrim')) return;
    if (!e.target.closest('#laNav')) laCloseNav();
  });
  var nav=document.getElementById('laNav');
  if (nav) nav.addEventListener('click', function(e){ if (e.target.closest('a')) laCloseNav(); });
  var side=document.getElementById('laSide');
  if (side) side.addEventListener('click', function(e){ if (e.target.closest('a')) laCloseNav(); });
  (function(){
    var meta = document.querySelector('meta[name="csrf-token"]');
    var tok = meta ? meta.getAttribute('content') : '';
    document.querySelectorAll('form[method="post"], form[method="POST"]').forEach(function(f){
      if (tok && !f.querySelector('input[name="_csrf"]')) {
        var i = document.createElement('input');
        i.type = 'hidden'; i.name = '_csrf'; i.value = tok;
        f.appendChild(i);
      }
      f.addEventListener('submit', function(){
        var hp = f.querySelector('input[name="la_hp_x9"]');
        if (hp) hp.value = '';
      });
    });
  })();
  </script>
